INSERT INTO `aprendizaje_lecciones` VALUES (1,1,'Suma de números naturales','suma-numeros-naturales','Aprende a sumar números naturales y a resolver situaciones de la vida cotidiana usando la adición.','topic','+','emoji','','24 + 13 = 37',NULL,'Básica',35,1,1,'2026-06-23 23:02:12','2026-07-07 21:57:11'),(2,1,'Suma de fracciones','suma-fracciones','Aprende a sumar fracciones con el mismo o distinto denominador mediante ejercicios paso a paso.','topic','½','emoji',NULL,'1/2 + 1/3 = ?',NULL,'Básica',60,2,1,'2026-06-23 23:02:12','2026-06-23 23:41:11'),(7,6,'Ecuaciones lineales de una variable','ecuaciones-lineales-s1','En este tema aprenderás a resolver ecuaciones lineales de una variable en la forma \\(ax + b = c\\). El objetivo es identificar los números que acompañan a la variable, usar operaciones contrarias para despejar la \\(x\\) y comprobar que el resultado sea correcto. También se trabajará la idea de mantener el equilibrio en ambos lados de la ecuación. \\(\\)','topic','+','emoji','','',NULL,'Basica',30,10,1,'2026-06-25 15:38:57','2026-06-30 21:42:28');

